WITH lines AS (SELECT id, log_ts, level, latency_ms, k, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) li AS k, attr_value) SELECT level, k, CASE WHEN latency_ms >= 2237 THEN 'PREMIUM' ELSE 'STANDARD' END AS latency_ms_tier, SUM(CASE WHEN k = 'version' THEN latency_ms ELSE 0 END) AS version_latency_ms, APPROX_PERCENTILE(latency_ms, 0.9) AS latency_ms_p90, MIN(log_ts) AS first_log_ts, COUNT(DISTINCT id) AS distinct_ids, BIT_OR(latency_ms) AS latency_ms_bit_or, BIT_AND(latency_ms) AS latency_ms_bit_and FROM lines GROUP BY level, k, CASE WHEN latency_ms >= 2237 THEN 'PREMIUM' ELSE 'STANDARD' END
